#!/usr/bin/env python3
"""Generate a first-party smoke fixture only; never substitute user uploads in CI."""
import pathlib, zipfile, sys
target=pathlib.Path(sys.argv[1] if len(sys.argv)>1 else "trusted-fixture.zip")
kind=sys.argv[2] if len(sys.argv)>2 else "arcade"
if kind not in ("arcade","puzzle"): raise SystemExit("Only first-party fixture choices allowed")
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><link rel="icon" href="data:,"><title>Arena Runtime Fixture</title><style>body{margin:0;font:16px system-ui;background:#172338;color:white}main{max-width:100%;padding:12px;box-sizing:border-box;text-align:center}canvas{width:min(100%,600px);height:auto;display:block;margin:auto;background:#213e49}button{margin:8px;padding:10px}</style><main><h1>Trusted smoke fixture</h1><canvas width="600" height="300"></canvas><button>Tap</button><p id="score">0</p></main><script>let n=0,c=document.querySelector("canvas"),x=c.getContext("2d");x.fillStyle="#b8f178";x.fillRect(260,100,80,80);function hit(){document.querySelector("#score").textContent=++n}document.querySelector("button").onclick=hit;c.onclick=hit;document.onkeydown=hit;</script></html>'''
if kind=="puzzle":
    html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><link rel="icon" href="data:,"><title>Pattern Match Fixture</title><style>body{margin:0;background:#142332;color:#fff;font:16px system-ui;text-align:center}main{padding:16px;max-width:340px;margin:auto}#grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}button{min-height:52px;border:0;border-radius:8px;background:#385269;color:white;font-size:20px}.on{background:#b8f178;color:#152533}</style><main><h1>Pattern Match</h1><p>Tap a tile to switch its state.</p><button id="start">Start</button><div id="grid"></div><p id="score">Moves: 0</p></main><script>let moves=0;const grid=document.getElementById("grid"),score=document.getElementById("score");function reset(){moves=0;score.textContent="Moves: 0";grid.replaceChildren();for(let i=0;i<9;i++){let b=document.createElement("button");b.textContent=String(i+1);b.setAttribute("aria-label","Tile "+(i+1));b.onclick=()=>{b.classList.toggle("on");score.textContent="Moves: "+(++moves)};grid.append(b)}}document.getElementById("start").onclick=reset;reset();</script></html>'''
with zipfile.ZipFile(target,'w',zipfile.ZIP_DEFLATED) as z:z.writestr('index.html',html)
print(target)
